+                "pair": [{"Sequence": {"id": "A", "type_id": 0}}],
+                "special_tokens": {"<s>": {"id": "<s>", "ids": [0], "tokens": ["<s>"]}}},
+            "model": {"type": "WordLevel", "unk_token": "[UNK]",
+                "vocab": {"<s>": 0, "[UNK]": 1, "Hi": 2, "It": 3}},
